// ── selectors ────────────────────────────────────────────────────────────────
/** Everything a public route may legally render. Empty is a legitimate answer. */
export const publiclyDisplayableAssets: MediaAsset[] = mediaAssets.filter(
  (a) => a.usage === "attributed_display" && a.delivery === "public",
)

export function mediaByCategory(category: MediaCategory): MediaAsset[] {
  return mediaAssets.filter((a) => a.category === category)
}

export function mediaBySubject(subject: MediaSubject): MediaAsset[] {
  return mediaAssets.filter((a) => a.subject === subject)
}

export function mediaById(id: string): MediaAsset | null {
  return mediaAssets.find((a) => a.id === id) ?? null
}

/** The highest-value assets in the harvest: unit layouts and resort site plans. */
export const planAssets: MediaAsset[] = mediaAssets.filter(
  (a) => a.category === "floorplan" || a.category === "siteplan",
)

